"""Shared conversions for legacy CFG-02 storage conventions."""

from datetime import date
from decimal import Decimal, ROUND_HALF_UP


def _is_blank(value: str | None) -> bool:
    """Return whether a nullable legacy character value is blank."""
    return value is None or value.strip() == ""


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date, including its null sentinel, to ISO."""
    if _is_blank(yyyymmdd) or yyyymmdd == "00000000":
        return None

    if len(yyyymmdd) != 8 or not yyyymmdd.isdigit():
        raise ValueError("legacy date must be YYYYMMDD")

    try:
        parsed = date(
            int(yyyymmdd[0:4]),
            int(yyyymmdd[4:6]),
            int(yyyymmdd[6:8]),
        )
    except ValueError as exc:
        raise ValueError("legacy date must be a valid YYYYMMDD date") from exc

    return parsed.isoformat()


def from_iso(iso: str | None) -> str:
    """Convert an ISO date to legacy YYYYMMDD, using the legacy null sentinel."""
    if _is_blank(iso):
        return "00000000"

    try:
        parsed = date.fromisoformat(iso)
    except ValueError as exc:
        raise ValueError("ISO date must be a valid YYYY-MM-DD date") from exc

    if len(iso) != 10 or iso != parsed.isoformat():
        raise ValueError("ISO date must be YYYY-MM-DD")

    return parsed.strftime("%Y%m%d")


def yn(char: str | None) -> bool:
    """Convert the legacy Y/N boolean representation to a Python bool."""
    return char == "Y"


def to_minor_units(amount, currency: str | None) -> int:
    """Convert a legacy decimal amount to rounded currency minor units."""
    if amount is None or (isinstance(amount, str) and amount.strip() == ""):
        return 0

    currency_code = "USD" if _is_blank(currency) else currency
    exponent = 0 if currency_code == "JPY" else 2

    decimal_amount = Decimal(str(amount))
    scale = Decimal(10) ** exponent
    return int((decimal_amount * scale).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
